import {useEffect,useState} from "react";
import {supabase} from "./lib/supabase";
import type {Category,Guide,Product} from "./types";
import {Plus,Save,Trash2,X,Search,Copy,RefreshCw,Upload} from "lucide-react";

type ProductFormState={title:string;slug:string;short_description:string;description:string;price:string;original_price:string;currency:string;rating:string;review_count:string;image_url:string;affiliate_url:string;brand:string;category_id:string;tags:string;key_features:string;is_featured:boolean;is_deal:boolean;is_active:boolean;is_sample:boolean};

const commonBrands=["Apple","Samsung","Sony","JBL","Anker","Xiaomi","OnePlus","Google","Microsoft","Nintendo","Lenovo","HP","Dell","ASUS","Acer","Logitech","Razer","Canon","Nikon","DJI","GoPro","Philips","LG","TCL","Dyson","Bosch","DeWalt","Makita","Nike","Adidas","Puma","Under Armour","LEGO","Hasbro","Mattel","Fisher-Price","Oral-B","Colgate","NIVEA","L'Oréal","Maybelline","The Ordinary","Generic / Unbranded"];
const emptyProduct:ProductFormState={title:"",slug:"",short_description:"",description:"",price:"",original_price:"",currency:"USD",rating:"0",review_count:"0",image_url:"",affiliate_url:"",brand:"",category_id:"",tags:"",key_features:"",is_featured:false,is_deal:false,is_active:true,is_sample:false};

async function uploadImage(file:File){
 const ext=file.name.split(".").pop()||"jpg"; const path=`products/${crypto.randomUUID()}.${ext}`;
 const {error}=await supabase.storage.from("affinova-media").upload(path,file,{upsert:false,contentType:file.type});
 if(error) throw error;
 return {path,publicUrl:supabase.storage.from("affinova-media").getPublicUrl(path).data.publicUrl};
}

function ProductForm({initial,categories,onSaved,onCancel}:{initial?:Product;categories:Category[];onSaved:()=>void;onCancel:()=>void}){
 const [f,setF]=useState<ProductFormState>(initial?{title:initial.title,slug:initial.slug,short_description:initial.short_description||"",description:initial.description||"",price:String(initial.price),original_price:initial.original_price?String(initial.original_price):"",currency:initial.currency,rating:String(initial.rating),review_count:String(initial.review_count),image_url:initial.image_url||"",affiliate_url:initial.affiliate_url||"",brand:initial.brand||"",category_id:initial.category_id||"",tags:(initial.tags||[]).join(", "),key_features:(initial.key_features||[]).join(", "),is_featured:initial.is_featured,is_deal:initial.is_deal,is_active:initial.is_active,is_sample:initial.is_sample}:emptyProduct);
 const [busy,setBusy]=useState(false),[msg,setMsg]=useState(""),[uploading,setUploading]=useState(false);
 const set=(k:keyof ProductFormState,v:string|boolean)=>setF(x=>({...x,[k]:v}));
 const pickImage=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){setMsg("Image must be 5MB or smaller.");return}setUploading(true);setMsg("");try{const r=await uploadImage(file);set("image_url",r.publicUrl)}catch(err){setMsg(err instanceof Error?err.message:"Upload failed")}finally{setUploading(false)}};
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setMsg("");const price=Number(f.price),original=f.original_price?Number(f.original_price):null,rating=Number(f.rating),reviews=Number(f.review_count);if(!f.title.trim()||!f.slug.trim()){setMsg("Title and slug are required.");return}if(!Number.isFinite(price)||price<0){setMsg("Enter a valid price.");return}if(original!==null&&(!Number.isFinite(original)||original<0)){setMsg("Enter a valid original price.");return}if(!Number.isFinite(rating)||rating<0||rating>5){setMsg("Rating must be between 0 and 5.");return}if(!Number.isInteger(reviews)||reviews<0){setMsg("Review count must be a whole number.");return}if(!/^https?:\/\//i.test(f.affiliate_url.trim())){setMsg("Enter a valid affiliate URL starting with http:// or https://.");return}if(f.image_url.trim()&&!/^https?:\/\//i.test(f.image_url.trim())){setMsg("Image URL must start with http:// or https://.");return}setBusy(true);const row={title:f.title.trim(),slug:f.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""),short_description:f.short_description||null,description:f.description||null,price,original_price:original,currency:f.currency.trim().toUpperCase()||"USD",rating,review_count:reviews,image_url:f.image_url||null,affiliate_url:f.affiliate_url||null,brand:f.brand||null,category_id:f.category_id||null,tags:f.tags.split(",").map(x=>x.trim()).filter(Boolean),key_features:f.key_features.split(",").map(x=>x.trim()).filter(Boolean),is_featured:f.is_featured,is_deal:f.is_deal,is_active:f.is_active,is_sample:f.is_sample};const q=initial?supabase.from("products").update(row).eq("id",initial.id):supabase.from("products").insert(row);const {error}=await q;if(error)setMsg(error.message);else onSaved();if(error&&!initial&&f.image_url){try{const path=f.image_url.split("/affinova-media/")[1];if(path)await supabase.storage.from("affinova-media").remove([decodeURIComponent(path)])}catch{} }setBusy(false)};
 return <div className="modal-backdrop"><form className="product-form" onSubmit={submit}><div className="form-head"><div><span className="eyebrow">{initial?"Edit":"New"} product</span><h2>{initial?"Update product":"Add product"}</h2></div><button type="button" className="close" onClick={onCancel}><X/></button></div><div className="form-grid"><label>Title<input required value={f.title} onChange={e=>set("title",e.target.value)}/></label><label>Slug<input required value={f.slug} onChange={e=>set("slug",e.target.value)}/></label><label>Category<select value={f.category_id} onChange={e=>set("category_id",e.target.value)}><option value="">No category</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Brand<select value={commonBrands.includes(f.brand)?f.brand:f.brand?"__manual__":""} onChange={e=>{const v=e.target.value;set("brand",v==="__manual__"?f.brand:v)}}><option value="">Select brand</option>{commonBrands.map(b=><option key={b} value={b}>{b}</option>)}<option value="__manual__">Other — enter manually</option></select></label>{(!commonBrands.includes(f.brand)||f.brand==="")&&<label>Manual brand<input value={commonBrands.includes(f.brand)?"":f.brand} onChange={e=>set("brand",e.target.value)} placeholder="e.g. Baseus, UGREEN, etc."/></label>}<label>Price<input required type="number" step="0.01" value={f.price} onChange={e=>set("price",e.target.value)}/></label><label>Original price<input type="number" step="0.01" value={f.original_price} onChange={e=>set("original_price",e.target.value)}/></label><label>Currency<input value={f.currency} onChange={e=>set("currency",e.target.value.toUpperCase())}/></label><label>Rating<input type="number" min="0" max="5" step=".1" value={f.rating} onChange={e=>set("rating",e.target.value)}/></label><label>Review count<input type="number" min="0" value={f.review_count} onChange={e=>set("review_count",e.target.value)}/></label><label className="wide">Image URL<input value={f.image_url} onChange={e=>set("image_url",e.target.value)} placeholder="https://..."/></label><label className="wide">Upload image<input type="file" accept="image/*" onChange={pickImage}/><small>{uploading?"Uploading...":"Max 5MB • Supabase Storage"}</small></label><label className="wide">AliExpress affiliate URL<input value={f.affiliate_url} onChange={e=>set("affiliate_url",e.target.value)} placeholder="https://s.click.aliexpress.com/..."/></label><label className="wide">Tags <small>comma separated</small><input value={f.tags} onChange={e=>set("tags",e.target.value)}/></label><label className="wide">Key features <small>comma separated</small><input value={f.key_features} onChange={e=>set("key_features",e.target.value)}/></label><label className="wide">Short description<textarea value={f.short_description} onChange={e=>set("short_description",e.target.value)}/></label><label className="wide">Description<textarea rows={5} value={f.description} onChange={e=>set("description",e.target.value)}/></label></div><div className="checks"><label><input type="checkbox" checked={f.is_featured} onChange={e=>set("is_featured",e.target.checked)}/> Featured</label><label><input type="checkbox" checked={f.is_deal} onChange={e=>set("is_deal",e.target.checked)}/> Deal</label><label><input type="checkbox" checked={f.is_active} onChange={e=>set("is_active",e.target.checked)}/> Active</label><label><input type="checkbox" checked={f.is_sample} onChange={e=>set("is_sample",e.target.checked)}/> Sample</label></div>{msg&&<div className="notice">{msg}</div>}<div className="form-actions"><button type="button" className="btn" onClick={onCancel}>Cancel</button><button className="btn primary" disabled={busy||uploading}><Save size={15}/> {busy?"Saving...":"Save product"}</button></div></form></div>
}

function CategoryForm({initial,onSaved,onCancel}:{initial?:Category;onSaved:()=>void;onCancel:()=>void}){
 const [f,setF]=useState({name:initial?.name||"",slug:initial?.slug||"",description:initial?.description||"",icon:initial?.icon||"",image_url:initial?.image_url||"",is_active:initial?.is_active??true,sort_order:String(initial?.sort_order??0)}),[busy,setBusy]=useState(false),[msg,setMsg]=useState("");
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setMsg("");const name=f.name.trim(),slug=f.slug.trim().toLowerCase().replace(/\\s+/g,"-").replace(/[^a-z0-9-]/g,"").replace(/-+/g,"-").replace(/^-|-$/g,"");const sort=Number(f.sort_order);if(!name||!slug){setMsg("Name and a valid slug are required.");return}if(!Number.isInteger(sort)||sort<0){setMsg("Sort order must be a non-negative whole number.");return}setBusy(true);const row={name,slug,description:f.description.trim()||null,icon:f.icon.trim()||null,image_url:f.image_url.trim()||null,is_active:f.is_active,sort_order:sort};const q=initial?supabase.from("categories").update(row).eq("id",initial.id):supabase.from("categories").insert(row);const {error}=await q;if(error)setMsg(error.message);else onSaved();setBusy(false)};
 return <div className="modal-backdrop"><form className="product-form" onSubmit={submit}><div className="form-head"><div><span className="eyebrow">Category</span><h2>{initial?"Edit category":"Add category"}</h2></div><button type="button" className="close" onClick={onCancel}><X/></button></div><div className="form-grid"><label>Name<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Slug<input required value={f.slug} onChange={e=>setF({...f,slug:e.target.value})}/></label><label>Icon<input value={f.icon} onChange={e=>setF({...f,icon:e.target.value})}/></label><label>Sort order<input type="number" value={f.sort_order} onChange={e=>setF({...f,sort_order:e.target.value})}/></label><label className="wide">Image URL<input value={f.image_url} onChange={e=>setF({...f,image_url:e.target.value})}/></label><label className="wide">Description<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label></div><div className="checks"><label><input type="checkbox" checked={f.is_active} onChange={e=>setF({...f,is_active:e.target.checked})}/> Active</label></div>{msg&&<div className="notice">{msg}</div>}<div className="form-actions"><button type="button" className="btn" onClick={onCancel}>Cancel</button><button className="btn primary" disabled={busy}><Save size={15}/> {busy?"Saving...":"Save category"}</button></div></form></div>
}


type PageRow={id:string;slug:string;title:string;content:string;excerpt:string|null;seo_title:string|null;seo_description:string|null;is_published:boolean;published_at:string|null};
type MediaRow={id:string;name:string;storage_path:string;public_url:string;mime_type:string|null;size_bytes:number|null;alt_text:string|null;created_at:string};
type EditorProps={value:string;onChange:(v:string)=>void};

function cleanHtml(html:string){
 const doc=new DOMParser().parseFromString(html,"text/html");
 doc.querySelectorAll("script,iframe,object,embed,style").forEach(x=>x.remove());
 doc.querySelectorAll("*").forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name))el.removeAttribute(a.name)});const href=el.getAttribute("href");if(href&&/^\s*javascript:/i.test(href))el.removeAttribute("href")});
 return doc.body.innerHTML;
}
function RichEditor({value,onChange}:EditorProps){
 const exec=(cmd:string,arg?:string)=>{document.execCommand(cmd,false,arg);onChange(cleanHtml((document.querySelector("[data-rich-editor='active']") as HTMLElement)?.innerHTML||""))};
 return <div className="rich-editor"><div className="rich-toolbar">
 <button type="button" onClick={()=>exec("bold")}><b>B</b></button><button type="button" onClick={()=>exec("italic")}><i>I</i></button><button type="button" onClick={()=>exec("underline")}><u>U</u></button><button type="button" onClick={()=>exec("formatBlock","<h2>")}>H2</button><button type="button" onClick={()=>exec("formatBlock","<h3>")}>H3</button><button type="button" onClick={()=>exec("insertUnorderedList")}>• List</button><button type="button" onClick={()=>exec("insertOrderedList")}>1. List</button><button type="button" onClick={()=>{const url=window.prompt("Link URL");if(url)exec("createLink",url)}}>Link</button><button type="button" onClick={()=>exec("removeFormat")}>Clear</button>
 </div><div className="rich-content" data-rich-editor="active" contentEditable suppressContentEditableWarning onInput={e=>onChange(cleanHtml(e.currentTarget.innerHTML))} dangerouslySetInnerHTML={{__html:cleanHtml(value||"")}} /></div>
}
async function uploadAdminMedia(file:File,folder:string){
 if(file.size>8*1024*1024)throw new Error("File must be 8MB or smaller.");
 const ext=file.name.split(".").pop()||"bin";const path=folder+"/"+crypto.randomUUID()+"."+ext;
 const {error}=await supabase.storage.from("affinova-media").upload(path,file,{upsert:false,contentType:file.type});if(error)throw error;
 return {path,publicUrl:supabase.storage.from("affinova-media").getPublicUrl(path).data.publicUrl};
}
