 const submit=async(e:React.FormEvent)=>{e.preventDefault();setMsg("");const slug=f.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");if(!f.title.trim()||!slug||!f.content.trim()){setMsg("Title, valid slug and content are required.");return}if(f.cover_image.trim()&&!/^https?:\/\//i.test(f.cover_image.trim())){setMsg("Cover image URL must start with http:// or https://.");return}if(f.og_image.trim()&&!/^https?:\/\//i.test(f.og_image.trim())){setMsg("OG image URL must start with http:// or https://.");return}setBusy(true);const row={title:f.title.trim(),slug,excerpt:f.excerpt.trim()||null,content:cleanHtml(f.content),cover_image:f.cover_image||null,category:f.category||null,author:f.author||null,seo_title:f.seo_title||null,seo_description:f.seo_description||null,seo_keywords:f.seo_keywords||null,og_image:f.og_image||null,is_published:f.is_published,published_at:f.is_published?(f.published_at?new Date(f.published_at).toISOString():new Date().toISOString()):null};const q=initial?supabase.from("guides").update(row).eq("id",initial.id):supabase.from("guides").insert(row);const {error}=await q;if(error)setMsg(error.message);else onSaved();setBusy(false)};
 return <div className="modal-backdrop"><form className="product-form" onSubmit={submit}><div className="form-head"><div><span className="eyebrow">Guide editor</span><h2>{initial?"Edit guide":"Add guide"}</h2></div><button type="button" className="close" onClick={onCancel}><X/></button></div><div className="form-grid">
 <label>Title<input required value={f.title} onChange={e=>setF({...f,title:e.target.value})}/></label><label>Slug<input required value={f.slug} onChange={e=>setF({...f,slug:e.target.value})}/></label><label>Category<input value={f.category} onChange={e=>setF({...f,category:e.target.value})}/></label><label>Author<input value={f.author} onChange={e=>setF({...f,author:e.target.value})}/></label><label className="wide">Cover image URL<input value={f.cover_image} onChange={e=>setF({...f,cover_image:e.target.value})}/></label><label className="wide">Upload cover<input type="file" accept="image/*" onChange={cover}/><small>{uploading?"Uploading...":"Max 8MB • Supabase Storage"}</small></label><label className="wide">Excerpt<textarea value={f.excerpt} onChange={e=>setF({...f,excerpt:e.target.value})}/></label><label className="wide">Content<RichEditor value={f.content} onChange={v=>setF({...f,content:v})}/></label><label>SEO title<input value={f.seo_title} onChange={e=>setF({...f,seo_title:e.target.value})}/></label><label>SEO keywords<input value={f.seo_keywords} onChange={e=>setF({...f,seo_keywords:e.target.value})}/></label><label className="wide">SEO description<textarea value={f.seo_description} onChange={e=>setF({...f,seo_description:e.target.value})}/></label><label className="wide">OG image URL<input value={f.og_image} onChange={e=>setF({...f,og_image:e.target.value})}/></label><label>Publish date<input type="datetime-local" value={f.published_at} onChange={e=>setF({...f,published_at:e.target.value})}/></label></div><div className="checks"><label><input type="checkbox" checked={f.is_published} onChange={e=>setF({...f,is_published:e.target.checked})}/> Published</label></div>{msg&&<div className="notice">{msg}</div>}<div className="form-actions"><button type="button" className="btn" onClick={onCancel}>Cancel</button><button className="btn primary" disabled={busy||uploading}><Save size={15}/> {busy?"Saving...":"Save guide"}</button></div></form></div>
