 const submit=async(e:React.FormEvent)=>{e.preventDefault();setMsg("");const slug=f.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");if(!slug||!f.title.trim()){setMsg("Title and valid slug are required.");return}setBusy(true);const row={slug,title:f.title.trim(),excerpt:f.excerpt.trim()||null,content:cleanHtml(f.content),seo_title:f.seo_title||null,seo_description:f.seo_description||null,is_published:f.is_published,published_at:f.is_published?(f.published_at?new Date(f.published_at).toISOString():new Date().toISOString()):null};const q=initial?supabase.from("content_pages").update(row).eq("id",initial.id):supabase.from("content_pages").insert(row);const {error}=await q;if(error)setMsg(error.message);else onSaved();setBusy(false)};
